import{_ as o,o as t,c as i,a2 as d}from"./chunks/framework.Boholvbs.js";const g=JSON.parse('{"title":"Configuration files","description":"How prioricode discovers and merges config (prioricode.json/jsonc, .prioricode/, managed dirs), {env} and {file} substitution, data paths, and database routing.","frontmatter":{"title":"Configuration files","description":"How prioricode discovers and merges config (prioricode.json/jsonc, .prioricode/, managed dirs), {env} and {file} substitution, data paths, and database routing."},"headers":[],"relativePath":"configure/files.md","filePath":"configure/files.md"}'),a={name:"configure/files.md"};function s(r,e,c,n,l,h){return t(),i("div",null,[...e[0]||(e[0]=[d(`<p>PrioriCode reads your config the way git reads dotfiles: look everywhere in a defined order, merge deeply, last word wins. This page is the full discovery map — for the individual keys, see the <a href="./../reference/config.html">config reference</a>.</p><h2 id="the-files" tabindex="-1">The files <a class="header-anchor" href="#the-files" aria-label="Permalink to &quot;The files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>What it&#39;s for</th></tr></thead><tbody><tr><td><code>prioricode.json</code> / <code>prioricode.jsonc</code></td><td>Product configuration (comments supported in <code>.jsonc</code>)</td></tr><tr><td><code>tui.json</code> / <code>tui.jsonc</code></td><td>Interface configuration — themes &amp; keybinds (<a href="./tui.html">next page</a>)</td></tr><tr><td><code>AGENTS.md</code> (+ <code>CLAUDE.md</code>, <code>CONTEXT.md</code>)</td><td>Project instructions (<a href="./../using/context.html">context</a>)</td></tr><tr><td><code>.prioricode/{agents,commands,skills,tools,plugin,themes}/</code></td><td>The extension folders (<a href="./../extending/skills.html">extending</a>)</td></tr><tr><td><code>&lt;data&gt;/auth.json</code></td><td>Stored provider credentials, mode <code>0600</code></td></tr><tr><td><code>&lt;data&gt;/prioricode*.db</code></td><td>Sessions and state (SQLite)</td></tr></tbody></table><p>New config files are seeded with <code>&quot;$schema&quot;: &quot;https://prioricode.ai/config.json&quot;</code> — that URL lights up autocomplete and validation in editors that support JSON Schema.</p><h2 id="where-it-looks-in-order" tabindex="-1">Where it looks, in order <a class="header-anchor" href="#where-it-looks-in-order" aria-label="Permalink to &quot;Where it looks, in order&quot;">​</a></h2><p>Priority runs bottom-up (later layers override earlier; deep-merged):</p><ol><li><strong>Remote well-known configs</strong> — any <code>providers login &lt;url&gt;</code> target contributes its advertised <code>config</code>.</li><li><strong>Global config dir</strong> — <code>~/.config/prioricode</code> (XDG; <code>PRIORICODE_CONFIG_DIR</code> relocates it): <code>config.json</code> → <code>prioricode.json</code> → <code>prioricode.jsonc</code>.</li><li><code>PRIORICODE_CONFIG</code> — one extra file, anywhere.</li><li><strong>Project files</strong> — <code>prioricode.json(c)</code> walked from your cwd <strong>up to the worktree root</strong>; root-first, so the file closest to you has the highest say.</li><li><strong>Config directories</strong> — the global dir, every <code>.prioricode/</code> between cwd and root, <code>~/.prioricode</code>, and <code>PRIORICODE_CONFIG_DIR</code>: each contributes config files, agents, commands, skills, tools, themes, and plugins.</li><li><code>PRIORICODE_CONFIG_CONTENT</code> — inline JSON(C) as a final local layer. (Great for CI: no files on disk.)</li><li><strong>Console org config</strong> — if you&#39;re logged into a PrioriCode org, its config is fetched and merged.</li><li><strong>Managed config</strong> — <code>prioricode.json(c)</code> in the system dirs: <code>/Library/Application Support/prioricode</code> (macOS), <code>%ProgramData%\\prioricode</code> (Windows), <code>/etc/prioricode</code> (Linux).</li><li><strong>macOS managed preferences</strong> — the <code>ai.prioricode.managed</code> <code>.mobileconfig</code> domain. Overrules everything above.</li></ol><p>Escape hatches: <code>PRIORICODE_DISABLE_PROJECT_CONFIG=1</code> skips project discovery entirely (repo can&#39;t configure your machine), and <code>--pure</code> skips external plugins.</p><p><code>.prioricode/</code> gets bootstrapped politely: a <code>.gitignore</code> so local junk stays local, and <code>@prioricode/plugin</code> installed for file plugins and typed custom tools.</p><h2 id="substitution" tabindex="-1">Substitution <a class="header-anchor" href="#substitution" aria-label="Permalink to &quot;Substitution&quot;">​</a></h2><p>Any config text supports two templates:</p><div class="language-jsonc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;model&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;{env:PRIORICODE_MODEL}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;provider&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;acme&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;options&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;apiKey&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;{file:./secrets/acme.key}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>{env:VAR}</code> pulls an environment variable; <code>{file:path}</code> reads a file (relative to the config file&#39;s directory, <code>~/</code> expanded). Secrets stay in files, patterns stay in git.</p><h2 id="where-prioricode-puts-its-things" tabindex="-1">Where PrioriCode puts its things <a class="header-anchor" href="#where-prioricode-puts-its-things" aria-label="Permalink to &quot;Where PrioriCode puts its things&quot;">​</a></h2><p>All XDG-standard, all overridable via the usual <code>XDG_*</code> env vars:</p><table tabindex="0"><thead><tr><th>Path</th><th>Contents</th></tr></thead><tbody><tr><td><code>~/.local/share/prioricode</code> (data)</td><td><code>prioricode.db</code>, <code>auth.json</code>, <code>mcp-auth.json</code>, <code>log/</code>, <code>plans/</code>, <code>tool-output/</code>, <code>repos/</code>, <code>snapshot/</code></td></tr><tr><td><code>~/.config/prioricode</code> (config)</td><td>global config dir (see above)</td></tr><tr><td><code>~/.cache/prioricode</code> (cache)</td><td>cached model catalog, skill packs, <code>bin/</code></td></tr><tr><td><code>~/.local/state/prioricode</code> (state)</td><td>recently-used models, misc state</td></tr><tr><td><code>$TMPDIR/prioricode</code> (tmp)</td><td>scratch</td></tr></tbody></table><p>Print the truth for your machine with <code>prioricode debug paths</code>, and <code>prioricode db path</code> for the database specifically.</p><h3 id="which-database-exactly" tabindex="-1">Which database, exactly <a class="header-anchor" href="#which-database-exactly" aria-label="Permalink to &quot;Which database, exactly&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Your build&#39;s channel</th><th>DB file (under data dir)</th></tr></thead><tbody><tr><td><code>latest</code>, <code>beta</code>, <code>prod</code>, or running from source (<code>local</code>)</td><td><code>prioricode.db</code> — shared, so sessions/projects/coordination carry across</td></tr><tr><td>any other channel (e.g. a desktop <code>dev</code> build)</td><td><code>prioricode-&lt;channel&gt;.db</code> — deliberately isolated</td></tr><tr><td><code>PRIORICODE_DISABLE_CHANNEL_DB=1</code></td><td>forces <code>prioricode.db</code></td></tr><tr><td><code>PRIORICODE_DB=/some/path</code></td><td>that path, full stop (<code>:memory:</code> works too)</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Two processes with <em>different</em> DB files will cheerfully not coordinate — that&#39;s the #1 &quot;why don&#39;t my sessions see each other?&quot; cause. Run <code>prioricode db path</code> in each process when <a href="./../using/coordination.html">coordination</a> looks deaf. And <code>PRIORICODE_DB</code> is a sledgehammer: it relocates <em>all</em> state, including credentials&#39; neighborhood.</p></div><h2 id="effective-config-debugging" tabindex="-1">Effective-config debugging <a class="header-anchor" href="#effective-config-debugging" aria-label="Permalink to &quot;Effective-config debugging&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> debug</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # the merged result, what the app actually sees</span></span></code></pre></div><p>Precedence fights are resolved by inspection, not archaeology.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../reference/config.html">Config reference</a> — Every key, type, and default. <ul><li><a href="./../reference/environment-variables.html">Environment variables</a> — Every <code>PRIORICODE_*</code> switch.</li><li><a href="./tui.html">TUI config</a> — The <code>tui.json</code> half of the split.</li><li><a href="./../using/context.html">Project context</a> — AGENTS.md loading rules.</li></ul></li></ul>`,25)])])}const u=o(a,[["render",s]]);export{g as __pageData,u as default};
